//go:build e2e

package main

import (
	"bytes"
	"crypto/tls"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// TestPlatformRunsAnApp follows a platform from a fresh Debian 13 to an
// app deployed by its key: a server in a container (systemd, SSH, Docker
// inside), prepared by task bootstrap's playbooks, an app generated by
// esquadro with the deploy blueprint, built and pushed to a registry on
// the server, deployed, then a broken version that goes back by itself.
// It needs Docker, Ansible and SOPS with age; run it with task e2e:platform.
func TestPlatformRunsAnApp(t *testing.T) {
	for _, tool := range []string{"docker", "ansible-playbook", "sops", "age-keygen", "ssh-keygen"} {
		if _, err := exec.LookPath(tool); err != nil {
			t.Fatalf("%s is not installed", tool)
		}
	}
	root := t.TempDir()
	p := &platformE2E{t: t, root: root}

	// A Debian 13 "VPS", reachable as root with a key.
	p.run("", nil, "docker", "build", "-q", "-t", "esquadro-e2e-debian", "testdata/debian")
	p.run(root, nil, "ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-f", "admin")
	p.run(root, nil, "ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-f", "deploy")
	name := fmt.Sprintf("esquadro-e2e-vps-%d", time.Now().UnixNano())
	p.run("", nil, "docker", "run", "-d", "--name", name, "--privileged", "--cgroupns=host",
		"-v", "/sys/fs/cgroup:/sys/fs/cgroup:rw", "--tmpfs", "/run", "--tmpfs", "/run/lock",
		"-v", name+"-docker:/var/lib/docker", "-v", name+"-containerd:/var/lib/containerd",
		"-p", "127.0.0.1::22", "-p", "127.0.0.1::443", "esquadro-e2e-debian")
	t.Cleanup(func() {
		exec.Command("docker", "rm", "-f", name).Run()
		exec.Command("docker", "volume", "rm", name+"-docker", name+"-containerd").Run()
	})
	p.vps = name
	p.ssh, p.https = p.port("22"), p.port("443")
	p.waitFor("SSH", func() bool {
		return exec.Command("docker", "exec", name, "systemctl", "is-active", "ssh").Run() == nil
	})
	p.run("", nil, "docker", "cp", filepath.Join(root, "admin.pub"), name+":/root/.ssh/authorized_keys")
	p.run("", nil, "docker", "exec", name, "sh", "-c", "chown root:root /root/.ssh/authorized_keys && chmod 600 /root/.ssh/authorized_keys")

	// The app: an HTTP service with a database, a worker and its deploy.
	app := filepath.Join(root, "shop")
	p.esquadro("new", "-blueprints", "app,env,domain,http,worker,postgres,migrations,docker,github_actions,deploy", "-module", "example.com/shop", "-no-git", "-no-gen", app)
	os.WriteFile(filepath.Join(app, "esquadro", "catalog.esq"), []byte("package catalog\n\nentity Product {\n  name string required\n}\n"), 0o644)
	p.esquadro("gen", app)
	p.run(app, nil, "docker", "build", "-q", "-t", "localhost:5000/shop:1.0.0", "--build-arg", "VERSION=1.0.0", ".")
	broken := filepath.Join(root, "broken")
	os.MkdirAll(broken, 0o755)
	os.WriteFile(filepath.Join(broken, "Dockerfile"), []byte("FROM localhost:5000/shop:1.0.0\nHEALTHCHECK --interval=2s --timeout=2s --start-period=1s --retries=2 CMD [\"/app/shop\", \"nope\"]\n"), 0o644)
	p.run(broken, nil, "docker", "build", "-q", "-t", "localhost:5000/shop:1.0.1", ".")

	// The platform: Caddy with its own certificates (nobody reaches this
	// server from the internet), PostgreSQL, and the app.
	plat := filepath.Join(root, "acme")
	p.esquadro("new", "-starter", "platform", "-no-git", "-no-gen", plat)
	model := filepath.Join(plat, "esquadro", "platform.esq")
	src, _ := os.ReadFile(model)
	s := strings.NewReplacer(
		"  blueprint caddy\n", "  blueprint caddy {\n    certificates internal\n    cloudflare   false\n  }\n",
		"  blueprint observability\n", "",
		"203.0.113.10", "127.0.0.1",
	).Replace(string(src))
	s += "\napp shop {\n  image   \"localhost:5000/shop\"\n  domains [\"shop.test\"]\n  worker\n  database\n}\n"
	os.WriteFile(model, []byte(s), 0o644)
	p.esquadro("gen", plat)

	env := []string{
		"SOPS_AGE_KEY_FILE=" + filepath.Join(root, "age.txt"),
		"ANSIBLE_CONFIG=ansible/ansible.cfg",
		"ANSIBLE_SSH_ARGS=-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ControlMaster=auto -o ControlPersist=60s",
		"ANSIBLE_PRIVATE_KEY_FILE=" + filepath.Join(root, "admin"),
	}
	if path := ansibleCollections(); path != "" {
		env = append(env, "ANSIBLE_COLLECTIONS_PATH="+path)
	}
	extra := []string{"-e", "ansible_port=" + p.ssh, "-e", "platform_ssh_key=" + filepath.Join(root, "admin.pub")}
	p.run(plat, env, "sh", "scripts/secrets-init.sh")
	os.MkdirAll(filepath.Join(plat, "deploy-keys"), 0o755)
	pub, _ := os.ReadFile(filepath.Join(root, "deploy.pub"))
	os.WriteFile(filepath.Join(plat, "deploy-keys", "shop.pub"), pub, 0o644)

	// task bootstrap: root once, then the admin user; root has no login.
	p.run(plat, env, "ansible-playbook", append([]string{"ansible/bootstrap.yml"}, extra...)...)
	p.run(plat, env, "ansible-playbook", append([]string{"ansible/site.yml"}, extra...)...)
	if err := p.sshAs("root", "admin", "true"); err == nil {
		t.Fatal("root still signs in")
	}
	if out := p.run(plat, env, "ansible-playbook", append([]string{"ansible/site.yml"}, extra...)...); !strings.Contains(out, "changed=0") {
		t.Fatalf("a second apply changed something:\n%s", out)
	}

	// The app's images, in a registry on the server.
	p.run("", nil, "docker", "exec", name, "docker", "run", "-d", "--restart", "always", "-p", "127.0.0.1:5000:5000", "--name", "registry", "registry:2")
	for _, v := range []string{"1.0.0", "1.0.1"} {
		p.pipe("docker save localhost:5000/shop:"+v, "docker exec -i "+name+" docker load")
		p.run("", nil, "docker", "exec", name, "docker", "push", "-q", "localhost:5000/shop:"+v)
	}

	// The deploy, as the app's CI makes it: its key, the tag.
	if out, err := p.deploy("v1.0.0"); err != nil || !strings.Contains(out, "shop 1.0.0 running") {
		t.Fatalf("deploy v1.0.0: %v\n%s", err, out)
	}
	if code := p.get("shop.test", "/healthz"); code != http.StatusNoContent {
		t.Fatalf("GET https://shop.test/healthz: %d", code)
	}
	if out := p.run("", nil, "docker", "exec", name, "docker", "exec", "postgres", "psql", "-U", "postgres", "-d", "shop", "-Atc", "select count(*) from products"); strings.TrimSpace(out) != "0" {
		t.Fatalf("the migration made no products table: %s", out)
	}

	// A broken version goes back to the one before, and the deploy fails.
	if out, err := p.deploy("v1.0.1"); err == nil || !strings.Contains(out, "back to 1.0.0") {
		t.Fatalf("deploy v1.0.1: %v\n%s", err, out)
	}
	if code := p.get("shop.test", "/healthz"); code != http.StatusNoContent {
		t.Fatalf("after the rollback, GET https://shop.test/healthz: %d", code)
	}

	// The key deploys versions of its app, and nothing else.
	for _, cmd := range []string{"v1.0.0; touch /tmp/owned", "blog v1.0.0", "sh"} {
		if out, err := p.deploy(cmd); err == nil || !strings.Contains(out, "must look like v1.2.3") {
			t.Fatalf("%q: %v\n%s", cmd, err, out)
		}
	}
}

type platformE2E struct {
	t          *testing.T
	root, vps  string
	ssh, https string
}

func (p *platformE2E) esquadro(args ...string) {
	p.t.Helper()
	var out bytes.Buffer
	if code := run(args, &out, &out); code != 0 {
		p.t.Fatalf("esquadro %s: exit %d\n%s", strings.Join(args, " "), code, out.String())
	}
}

func (p *platformE2E) run(dir string, env []string, name string, args ...string) string {
	p.t.Helper()
	cmd := exec.Command(name, args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), env...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		p.t.Fatalf("%s %s: %v\n%s", name, strings.Join(args, " "), err, out)
	}
	return string(out)
}

func (p *platformE2E) pipe(from, to string) {
	p.t.Helper()
	p.run("", nil, "sh", "-c", from+" | "+to)
}

// port is the host port Docker gave the server's port.
func (p *platformE2E) port(port string) string {
	p.t.Helper()
	out := strings.TrimSpace(p.run("", nil, "docker", "port", p.vps, port))
	_, hostPort, err := net.SplitHostPort(strings.Split(out, "\n")[0])
	if err != nil {
		p.t.Fatalf("docker port %s: %q", port, out)
	}
	return hostPort
}

func (p *platformE2E) waitFor(what string, ok func() bool) {
	p.t.Helper()
	for range 60 {
		if ok() {
			return
		}
		time.Sleep(time.Second)
	}
	p.t.Fatalf("%s never came up", what)
}

func (p *platformE2E) sshArgs(key string) []string {
	return []string{"-o", "StrictHostKeyChecking=no", "-o", "UserKnownHostsFile=/dev/null", "-o", "LogLevel=ERROR",
		"-o", "IdentitiesOnly=yes", "-o", "BatchMode=yes", "-p", p.ssh, "-i", filepath.Join(p.root, key)}
}

func (p *platformE2E) sshAs(user, key, command string) error {
	return exec.Command("ssh", append(p.sshArgs(key), user+"@127.0.0.1", command)...).Run()
}

// deploy runs what the app's CI runs: its key, the tag as the command.
func (p *platformE2E) deploy(command string) (string, error) {
	cmd := exec.Command("ssh", append(p.sshArgs("deploy"), "deploy@127.0.0.1", command)...)
	cmd.Stdin = strings.NewReader("")
	out, err := cmd.CombinedOutput()
	return string(out), err
}

// get asks the server's Caddy for a path of a domain, waiting while an app
// is replaced.
func (p *platformE2E) get(host, path string) int {
	client := &http.Client{
		Timeout: time.Minute,
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{ServerName: host, InsecureSkipVerify: true},
		},
	}
	req, _ := http.NewRequest("GET", "https://127.0.0.1:"+p.https+path, nil)
	req.Host = host
	res, err := client.Do(req)
	if err != nil {
		p.t.Fatalf("GET https://%s%s: %v", host, path, err)
	}
	res.Body.Close()
	return res.StatusCode
}

// ansibleCollections is where the installed Ansible keeps its collections,
// when ansible-galaxy knows.
func ansibleCollections() string {
	out, err := exec.Command("ansible-galaxy", "collection", "list", "community.docker").Output()
	if err != nil {
		return ""
	}
	for line := range strings.SplitSeq(string(out), "\n") {
		if p, ok := strings.CutPrefix(line, "# "); ok && strings.HasSuffix(p, "ansible_collections") {
			return filepath.Dir(p)
		}
	}
	return ""
}
